-- Update exercise EN/AR descriptions from exercise-instructions-batches-1-5.docx
-- Generated: matches by normalized exercise name. 71 exact matches.
BEGIN;

UPDATE "Exercises" SET "Description" = 'Stand or sit with your elbow bent at 90 degrees and tucked to your side. Hold a light resistance band with your affected hand. Slowly rotate your forearm outward about 40 degrees, keeping the elbow fixed. Pause briefly at the end range. Return slowly to the starting position and repeat.', "DescriptionAr" = 'قف أو اجلس مع ثني الكوع بزاوية 90 درجة وتثبيته بجانب الجسم. أمسك شريط مقاومة خفيف باليد المصابة. أدر الساعد للخارج بحوالي 40 درجة مع تثبيت الكوع. توقف لحظة عند نهاية الحركة. عد ببطء إلى وضع البداية وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = '05bcc5d7-717f-4ba5-8193-5ef1a5d983cd';  -- 40 Degrees Shoulder External Rotation
UPDATE "Exercises" SET "Description" = 'Stand with feet shoulder-width apart and lean forward from the hips. Let the arm hang straight down while holding a light dumbbell. Slowly bend the elbow, bringing the weight toward the shoulder. Keep the upper arm still throughout the movement. Lower the weight with control and repeat.', "DescriptionAr" = 'قف والقدمان بعرض الكتفين وانحنِ للأمام من منطقة الوركين. اترك الذراع متدلية للأسفل ممسكاً بدمبل خفيف. اثنِ الكوع ببطء لرفع الوزن باتجاه الكتف. حافظ على ثبات الذراع العلوية طوال الحركة. أنزل الوزن بتحكم وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = 'fbe1fbbf-ffd1-4b38-80d3-727359a932b1';  -- Bent-Over Elbow Flexion
UPDATE "Exercises" SET "Description" = 'Sit upright with the affected arm resting on a table or your thigh. Use your non-affected hand to gently support the affected wrist. Slowly bend the affected elbow with help from the other hand. Bring the hand toward the shoulder as far as comfortable. Straighten the arm slowly and repeat.', "DescriptionAr" = 'اجلس بشكل مستقيم مع وضع الذراع المصابة على طاولة أو الفخذ. استخدم اليد السليمة لدعم رسغ الذراع المصابة بلطف. اثنِ كوع الذراع المصابة ببطء بمساعدة اليد الأخرى. قرّب اليد من الكتف بقدر ما تسمح الراحة. افرد الذراع ببطء وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = 'c480e213-ee64-4e1b-982b-288ebf3fce2d';  -- Active-Assisted Elbow Flexion
UPDATE "Exercises" SET "Description" = 'Stand or sit upright with arms relaxed at your sides. Interlock the fingers of both hands together in front of you. Let the non-affected arm guide the affected arm out to the side. Raise both arms sideways as high as comfortable. Lower slowly back to the starting position and repeat.', "DescriptionAr" = 'قف أو اجلس بشكل مستقيم مع إرخاء الذراعين بجانب الجسم. شبّك أصابع اليدين معاً أمامك. اجعل الذراع السليمة توجه الذراع المصابة للخارج. ارفع الذراعين للجانب لأعلى ارتفاع مريح. أنزلهما ببطء إلى وضع البداية وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'd51dc5ce-d0c4-4e03-89c2-c31578232d5b';  -- Active-Assisted Shoulder Abduction
UPDATE "Exercises" SET "Description" = 'Stand or sit upright while holding a stick with both hands in front. Use the non-affected arm to push the stick and affected arm upward. Raise both arms overhead as high as comfortable. Hold briefly at the top position. Lower the stick slowly and repeat.', "DescriptionAr" = 'قف أو اجلس بشكل مستقيم ممسكاً بعصا بكلتا اليدين أمامك. استخدم الذراع السليمة لدفع العصا والذراع المصابة للأعلى. ارفع الذراعين فوق الرأس لأقصى ارتفاع مريح. توقف لحظة عند الأعلى. أنزل العصا ببطء وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = 'e8f8ad2c-1304-43e5-a44e-edf34e3c90d1';  -- Active-Assisted Shoulder Flexion with Stick
UPDATE "Exercises" SET "Description" = 'Start on hands and knees in a quadrip position. Keep your back flat and core tucked. Extend the right arm forward and left leg backward at the same time. Hold for 2–3 seconds keeping the body stable. Return to start and switch sides.', "DescriptionAr" = 'ابدأ على اليدين والركبتين بوضع الرباعي. حافظ على ظهر مستقيم وشد عضلات البطن. مدّ الذراع اليمنى للأمام والساق اليسرى للخلف في نفس الوقت. ثبّت الوضع لمدة 2–3 ثوانٍ مع استقرار الجسم. عد لوضع البداية وبدّل الجانبين.', "UpdatedAt" = now() WHERE "ExerciseId" = '74790cc3-f078-47bb-9dd5-994aaf4b3cdb';  -- Alternate Arm & Leg Raises
UPDATE "Exercises" SET "Description" = 'Stand upright with arms straight down at your sides, palms forward. Slowly raise both arms out to the sides and overhead like making a snow angel. Keep the arms straight throughout the movement. Squeeze the shoulder blades together at the top. Lower the arms slowly and repeat.', "DescriptionAr" = 'قف بشكل مستقيم مع إنزال الذراعين وراحة اليدين للأمام. ارفع الذراعين ببطء إلى الجانبين ثم فوق الرأس كملاك الثلج. حافظ على استقامة الذراعين طول الحركة. اضغط لوحي الكتف معاً في الأعلى. أنزل الذراعين ببطء وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '6946d905-7904-4a05-9458-2dfc9fb0346e';  -- Angel Swings
UPDATE "Exercises" SET "Description" = 'Stand upright and bring one arm across your chest. Use the opposite hand to gently pull the arm closer. Slowly rotate your core in the same direction as the stretch. Hold for 20 - 30 seconds while breathing normally. Release and repeat on the other side.', "DescriptionAr" = 'قف بشكل مستقيم وضع إحدى الذراعين عبر الصدر. استخدام اليد الأخرى سحب الذراع بلطف نحو الجسم. أدر الجذع ببطء في نفس اتجاه الشد. ثبّت لمدة 20 - 30 ثانية مع التنفس الطبيعي. استرخِ وكرر على الجانب الآخر.', "UpdatedAt" = now() WHERE "ExerciseId" = '973ef956-6e71-4966-ac14-cc303a36c59b';  -- Arm Cross Stretch with Rotation
UPDATE "Exercises" SET "Description" = 'Lie on your back with knees flexed to 70 degrees and feet flat on the floor. Place a soft ball between your knees. Squeeze the ball firmly using your inner thigh muscles. Hold the squeeze for 5 seconds. Relax and repeat.', "DescriptionAr" = 'استلقِ على ظهرك مع ثني الركبتين الى 70 درجة ووضع القدمين على الأرض. ضع كرة طرية بين الركبتين. اضغط على الكرة بقوة باستخدام عضلات الفخذ الداخلية. ثبّت الضغطة لمدة 5 ثوانٍ. استرخِ وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = 'f898d223-6001-477d-8a92-fe1cb8d2a511';  -- Ball Squeeze Between Knees
UPDATE "Exercises" SET "Description" = 'Stand with feet shoulder-width apart and lean forward from the hips. Hold a light dumbbell in one hand with the arm hanging down. Raise one arm out to the side until parallel to the floor. Squeeze the shoulder blade together at the top. Lower the weight slowly and repeat.', "DescriptionAr" = 'قف و القدمين بعرض الكتفين وانحنِ للأمام من الوركين. أمسك دمبل خفيف بيد واحدة مع تدلي الذراع للأسفل. ارفع ذراعًا واحدة إلى الجانب حتى تصبح موازية للأرض. اضغط لوحي الكتف معًا في الأعلى. أنزل الوزن ببطء وكرر', "UpdatedAt" = now() WHERE "ExerciseId" = 'b1bb859d-9fc8-4bd1-b264-fea86b485313';  -- Bent-Over Lateral Raise
UPDATE "Exercises" SET "Description" = 'Stand on a resistance band with feet shoulder-width apart. Bend forward from the hips with knees slightly bent. Grip the band handles with arms hanging down. Pull the handles toward your ribs, squeezing shoulder blades. Lower slowly with control and repeat.', "DescriptionAr" = 'قف على شريط المقاومة والقدمان بعرض الكتفين. انحنِ للأمام من الوركين مع ثني الركبتين قليلاً. أمسك مقابض الشريط مع تدلي الذراعين للأسفل. اسحب المقابض نحو الأضلاع مع ضغط لوحي الكتف. انزل ببطء بتحكم وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = 'd2c73132-24b8-4950-883e-14eda721973f';  -- Bent-Over Resisted Rows
UPDATE "Exercises" SET "Description" = 'Stand with feet shoulder-width apart, knees slightly bent. Lean forward from the hips with your arms hanging down. Keep your back flat and core engaged. Pull your arms up toward your ribs, squeezing shoulder blades. Lower your arms slowly and repeat.', "DescriptionAr" = 'قف والقدمان بعرض الكتفين والركبتين مثنيتين قليلاً. انحنِ للأمام من الوركين مع تدلي الذراعين للأسفل. حافظ على ظهرك مستقيمًا وشد عضلات البطن. اسحب الذراعين نحو الأضلاع مع ضغط لوحي الكتف. أنزل الذراعين ببطء وكرر', "UpdatedAt" = now() WHERE "ExerciseId" = '908e67c3-c326-44dc-9170-5018a6bd93ad';  -- Bent-Over Rows
UPDATE "Exercises" SET "Description" = 'Stand or sit upright with arms relaxed at your sides. Interlock your fingers together and turn palms upward. Slowly raise both arms straight overhead. Reach as high as comfortable and hold 20 - 30 seconds. Lower the arms slowly and repeat.', "DescriptionAr" = 'قف أو اجلس بشكل مستقيم مع إرخاء الذراعين. شبّك الأصابع واقلب راحة اليدين للأعلى. ارفع الذراعين ببطء فوق الرأس مستقيمتين. امتد لأقصى ارتفاع مريح لمدة 30–20 ثانية. أنزل الذراعين ببطء وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'be6c9d0d-d911-441a-a19e-86aacd2a3926';  -- Both Arms Overhead Stretch
UPDATE "Exercises" SET "Description" = 'Lie on your back with legs straight. Bend both knees and bring them toward your chest. Wrap your arms around your shins. Gently pull the knees closer, feeling a stretch in the lower back. Hold 15 - 30 seconds then return to start.', "DescriptionAr" = 'استلقِ على ظهرك والساقان مستقيمتان. اثنِ الركبتين وقرّبهما من الصدر. لفّ ذراعيك حول الساقين. اسحب الركبتين بلطف مع الشعور بشد في أسفل الظهر. ثبّت لمدة 30-15 ثانية ثم بعد البداية.', "UpdatedAt" = now() WHERE "ExerciseId" = '1ce94c3c-acf7-40c2-8162-20af0d0d8643';  -- Both Knees to Chest
UPDATE "Exercises" SET "Description" = 'Sit on the floor with your back straight. Bring the soles of your feet together in front of you. Hold your feet with your hands and let knees fall outward. Gently press your knees toward the floor. Hold 20–30 seconds, breathing steadily.', "DescriptionAr" = 'اجلس على الأرض مع استقامة الظهر. اجمع باطن القدمين معاً أمامك. أمسك القدمين باليدين ودع الركبتين تسقطان للجانبين. اضغط الركبتين بلطف نحو الأرض. ثبّت لمدة 20–30 ثانية مع التنفس الهادئ.', "UpdatedAt" = now() WHERE "ExerciseId" = '362ccecf-1593-4551-b111-2f00145436b9';  -- Butterfly Stretch
UPDATE "Exercises" SET "Description" = 'Start on hands and knees in tabletop position. Inhale as you drop your belly and lift your head (Cow). Exhale as you round your spine and tuck your chin (Cat). Move slowly between the two positions. Repeat for 8–10 flowing cycles.', "DescriptionAr" = 'ابدأ على اليدين والركبتين بوضع الطاولة. استنشق وأنزل البطن وارفع الرأس (البقرة). ازفر وقوّس الظهر واضمّ الذقن (القطة). تحرك ببطء بين الوضعين. كرر لمدة 8–10 دورات متتابعة.', "UpdatedAt" = now() WHERE "ExerciseId" = 'cbceda85-c4bd-43b1-a0de-bf3fb4724214';  -- Cat-Cow Stretch
UPDATE "Exercises" SET "Description" = 'Stand upright with feet hip-width apart. Clasp your hands behind your lower back. Lift the chest and squeeze the shoulder blades together. Gently pull the arms down and back. Hold 15–20 seconds while breathing deeply.', "DescriptionAr" = 'قف بشكل مستقيم والقدمين بعرض الوركين. شبّك اليدين خلف أسفل الظهر. ارفع الصدر واضغط لوحي الكتف معاً. اسحب الذراعين بلطف للأسفل والخلف. ثبّت لمدة 15–20 ثانية مع التنفس العميق.', "UpdatedAt" = now() WHERE "ExerciseId" = '81d1ab10-ed9d-4ed4-8842-3395bcd7b321';  -- Chest Expansion
UPDATE "Exercises" SET "Description" = 'Kneel on the floor and sit back on your heels. Reach both arms forward on the ground. Lower your forehead toward the floor. Feel a stretch through the back and shoulders. Hold 30 seconds while breathing steadily.', "DescriptionAr" = 'اركع على الأرض ويجلس على كعبيك. مدّ الذراعين للأمام على الأرض. أنزل جبهتك نحو الأرض. اشعر بالشد في الظهر والكتفين. ثبّت لمدة 30 ثانية مع التنفس الهادئ.', "UpdatedAt" = now() WHERE "ExerciseId" = '566d8100-049d-41c3-9805-60f0eed72108';  -- Child Stretch
UPDATE "Exercises" SET "Description" = 'Lie face down with hands under your shoulders. Keep your hips and legs pressed to the floor. Push up through your arms, lifting the chest. Look slightly upward without straining the neck. Hold 20 - 30 seconds then lower down.', "DescriptionAr" = 'استلقِ على البطن ويداك تحت الكتفين. حافظ على تثبيت الوركين والساقين على الأرض. ادفع بالذراعين وارفع الصدر. انظر قليلاً للأعلى دون إجهاد الرقبة. ثبّت لمدة 30–20 ثانية ثم أنزل.', "UpdatedAt" = now() WHERE "ExerciseId" = 'd482f50d-cadf-4e60-ab87-ff76f80440b9';  -- Cobra Stretch
UPDATE "Exercises" SET "Description" = 'Start quadrep position with a flat back. Slide one arm under your body across to the opposite side. Rest your shoulder and head on the floor. Feel the stretch through the upper back and shoulder. Hold 20–30 seconds then switch sides.', "DescriptionAr" = 'ابدأ على اليدين والركبتين في الشكل الرباعي مع استقامة الظهر. مرّر إحدى الذراعين تحت الجسم للجانب الآخر. ضع الكتف والرأس على الأرض. اشعر بالشد في أعلى الظهر والكتف. ثبّت لمدة 20–30 ثانية ثم بدّل.', "UpdatedAt" = now() WHERE "ExerciseId" = '52df497b-636e-4e7f-981b-0c79a6782700';  -- Cross Arm in Quadruped Position
UPDATE "Exercises" SET "Description" = 'Lie on your back with knees bent. Cross the right ankle over the left thigh. Grasp behind the left thigh with both hands. Pull the left leg toward your chest. Hold 20–30 seconds then switch sides.', "DescriptionAr" = 'استلقِ على ظهرك مع ثني الركبتين. ضع كاحل القدم اليمنى على الفخذ الأيسر. أمسك خلف الفخذ الأيسر بكلتا اليدين. اسحب الساق اليسرى نحو الصدر. ثبّت لمدة 20–30 ثانية ثم بدّل.', "UpdatedAt" = now() WHERE "ExerciseId" = 'b6ab5197-4e2a-48e8-b00e-5a66e4b49fc3';  -- Cross-Leg Piriformis Stretch
UPDATE "Exercises" SET "Description" = 'Sit on the floor with one leg crossed over the other. Place the opposite elbow on the outside of the raised knee. Gently push the knee across the body while rotating the torso. Look over the shoulder of the twisted side. Hold 20–30 seconds then switch sides.', "DescriptionAr" = 'اجلس على الأرض مع تقاطع ساق فوق الأخرى. ضع الكوع المعاكس على خارج الركبة المرفوعة. ادفع الركبة بلطف عبر الجسم مع تدوير الجذع. انظر فوق الكتف في اتجاه اللف. ثبّت 20–30 ثانية ثم بدّل الجانبين.', "UpdatedAt" = now() WHERE "ExerciseId" = '71ebd883-428c-453b-85b8-01328c0e17b1';  -- Crossed Leg Push
UPDATE "Exercises" SET "Description" = 'Stand upright and cross one foot in front of the other. Keep the legs straight but not locked. Slowly bend forward from the hips. Reach your fingers toward your toes. Hold 15–25 seconds, then switch leg crossings.', "DescriptionAr" = 'قف بشكل مستقيم مع تقاطع قدم أمام الأخرى. حافظ على استقامة الساقين دون قفلهما. انحنِ ببطء للأمام من الوركين. مدّ الأصابع نحو أصابع القدمين. ثبّت 15–25 ثانية ثم بدّل التقاطع.', "UpdatedAt" = now() WHERE "ExerciseId" = 'f69afaac-86ce-4c80-9906-b55140c12233';  -- Crossed Legs Toe Touch
UPDATE "Exercises" SET "Description" = 'Sit on the floor with legs crossed. Keep your back upright and shoulders relaxed. Slowly bend your trunk forward from the hips. Reach your arms out along the floor. Hold 20–30 seconds then sit back up.', "DescriptionAr" = 'اجلس على الأرض مع تقاطع الساقين. حافظ على استقامة الظهر و استرخاء الكتفين. انحنِ بالجذع ببطء للأمام من الوركين. مدّ الذراعين على الأرض. ثبّت 20–30 ثانية ثم عاد للجلوس.', "UpdatedAt" = now() WHERE "ExerciseId" = '93b72579-fcb7-463b-b019-66e4a9ee3d79';  -- Crossed Legs Trunk Flexion
UPDATE "Exercises" SET "Description" = 'Lie on your back with knees bent to 70 degrees and feet flat on the floor. Place your hands lightly behind your head. Engage your core and lift your shoulders off the floor. Keep the lower back pressed to the ground. Lower slowly and repeat.', "DescriptionAr" = 'استلقِ على ظهرك مع ثني الركبتين الى 70 درجة ووضع القدمين على الأرض. وضع اليدين خلف الرأس بشكل خفيف. شدّ عضلات البطن وارفع الكتفين عن الأرض. حافظ على تثبيت أسفل الظهر على الأرض. انزل ببطء وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = 'd2da9e65-2e3b-4da3-a2d7-1f28e117d53f';  -- Crunches
UPDATE "Exercises" SET "Description" = 'Stand with feet hip-width apart. Bend at the hips and knees. Keep the back flat and chest lifted. Drive through the heels to stand up straight. Lower the weight with control and repeat.', "DescriptionAr" = 'قف والقدمان بعرض الوركين. انحنِ من الوركين والركبتين. حافظ على استقامة الظهر ورفع الصدر. ادفع من خلال الكعبين الوقوف باستقامة. أنزل الوزن بتحكم وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '7118e59c-d651-43f3-8dcb-ab10950880ab';  -- Deadlifts
UPDATE "Exercises" SET "Description" = 'Stand or sit upright with arms hanging at your sides. Keep your chest lifted and shoulders relaxed. Squeeze your shoulder blades together and downward. Hold the squeeze for 10 - 15 seconds. Release slowly and repeat.', "DescriptionAr" = 'قف أو اجلس بشكل مستقيم والذراعين متدليتان. حافظ على رفع الصدر و استرخاء الكتفين. اضغط لوحي الكتف معاً وللأسفل. ثبّت الضغطة لمدة 10 - 15 ثوانٍ. استرخِ ببطء وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = '7d48004f-058b-4005-8296-f8c0fef5e633';  -- Dropped Arms Scapular Squeeze
UPDATE "Exercises" SET "Description" = 'Sit or stand with the elbow bent at 90 degrees. Tuck the elbow close to your side. Hold a soft ball in your hand. Squeeze the ball firmly and hold for 5 seconds. Release slowly and repeat.', "DescriptionAr" = 'اجلس أو قف مع ثني الكوع بزاوية 90 درجة. ثبّت الكوع بجانب الجسم. أمسك كرة طرية باليد. اضغط الكرة بقوة وثبّت لمدة 5 ثوانٍ. استرخِ ببطء وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'fc56bed6-a039-4dbe-ae3e-d0d40e9074b1';  -- Elbow 90° Flexion with Ball Squeeze
UPDATE "Exercises" SET "Description" = 'Stand or sit upright with the arm at your side. Hold a light weight in your hand, palm facing up. Slowly bend the elbow, bringing the weight toward the shoulder. Keep the upper arm still throughout. Lower with control and repeat.', "DescriptionAr" = 'قف أو اجلس بشكل مستقيم والذراع بجانب الجسم. أمسك وزن خفيف باليد وراحة اليد للأعلى. اثنِ الكوع ببطء لرفع الوزن نحو الكتف. حافظ على ثبات الذراع العلوية. أنزل بتحكم وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = '648b218f-b2d8-4ec8-a3d9-d0031b00a60a';  -- Elbow Flexion
UPDATE "Exercises" SET "Description" = 'Sit or stand with your elbow bent at 90 degrees at your side. Keep the upper arm still throughout. Slowly bend the wrist upward, then downward. Move through the full comfortable range. Return to neutral and repeat.', "DescriptionAr" = 'اجلس أو قف مع ثني الكوع 90 درجة بجانب الجسم. حافظ على ثبات الذراع العلوية. اثنِ الرسغ ببطء للأعلى ثم للأسفل. تحرك عبر النطاق الكامل المريح. عد إلى الوضع المحايد وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '39a7716a-02fb-49ad-abd9-f2bfcf8040c4';  -- Elbow Flexion to 90° with Wrist Flexion/Extension
UPDATE "Exercises" SET "Description" = 'Sit or stand with the elbow bent at 90 degrees. Slowly close your fingers into a fist. Then open the fingers fully and stretch them out. Coordinate movement smoothly with the elbow bent. Repeat for the prescribed reps.', "DescriptionAr" = 'اجلس أو قف مع ثني الكوع 90 درجة. أغلق أصابعك ببطء لتكوين قبضة. ثم افتحها بالكامل ومدّها للخارج. نسّق الحركة بسلاسة مع ثني الكوع. كرر التمرين للعدد المطلوب.', "UpdatedAt" = now() WHERE "ExerciseId" = '95e9ff75-031a-4926-be25-f690cb8623d5';  -- Elbow Flexion with Fingers Flexion/Extension
UPDATE "Exercises" SET "Description" = 'Sit or stand with elbow bent at 90 degrees, fist closed. Keep the upper arm at your side. Punch forward by extending the elbow fully. Return the fist to the bent starting position. Repeat with a smooth, controlled tempo.', "DescriptionAr" = 'اجلس أو قف مع ثني الكوع 90 درجة وإغلاق القبضة. حافظ على الذراع العلوية بجانب الجسم. اضرب للأمام بمدّ الكوع بالكامل. أعد القبضة إلى وضع البداية المثنى. كرر بإيقاع سلس ومتحكم به.', "UpdatedAt" = now() WHERE "ExerciseId" = 'e7cf58e2-4464-4f01-87a7-422ae5ad9b1a';  -- Elbow Flexion with Punch
UPDATE "Exercises" SET "Description" = 'Sit or stand with the arm at your side. Bend the elbow while extending the wrist backward. Keep the upper arm still throughout. Bring the hand toward the shoulder with the wrist extended. Return slowly to start and repeat.', "DescriptionAr" = 'اجلس أو قف والذراع بجانب الجسم. اثنِ الكوع مع مدّ الرسغ للخلف. حافظ على ثبات الذراع العلوية. قرّب اليد من الكتف والرسغ ممدود. عد ببطء إلى البداية وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '80e4b4da-0cdc-46c9-80fb-de7ff3ad4937';  -- Elbow Flexion with Wrist Extension
UPDATE "Exercises" SET "Description" = 'Stand holding a resistance band anchored at hip level. Start with the hand at the opposite hip. Rotate the arm outward and upward on a diagonal. End with the arm above shoulder height, thumb up. Return slowly along the same diagonal and repeat.', "DescriptionAr" = 'قف ممسكاً بشريط مقاومة مثبت عند مستوى الورك. ابدأ واليد عند الورك المعاكس. أدر الذراع للخارج ولأعلى بشكل قطري. انهِ مع الذراع فوق مستوى الكتف و الإبهام للأعلى. عد ببطء بنفس الاتجاه القطري وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '259833fb-0713-43b3-a1d3-b4675864190b';  -- External Rotation Diagonal Up
UPDATE "Exercises" SET "Description" = 'Rest your hand flat on a table, palm down. Keep the wrist relaxed on the surface. Lift each finger off the table one at a time. Hold each lift for like 6 seconds at the top. Lower slowly and continue with all fingers.', "DescriptionAr" = 'ضع يدك مسطحة على طاولة وراحة اليد للأسفل. حافظ على استرخاء الرسغ على السطح. ارفع كل إصبع عن الطاولة واحداً تلو الآخر. ثبّت كل رفعة لمدة 6 ثواني في الأعلى. انزل ببطء وتابعت مع باقي الأصابع.', "UpdatedAt" = now() WHERE "ExerciseId" = '36b08cde-3cd5-4cb8-b5e4-b3c9dc05c7ba';  -- Finger Extension on Table
UPDATE "Exercises" SET "Description" = 'Place a rubber band around all your fingers and thumb. Keep the hand in a relaxed position. Slowly spread the fingers apart against the band''s resistance. Hold the open position for 3–5 seconds. Relax and repeat.', "DescriptionAr" = 'ضع شريطاً مطاطياً حول جميع الأصابع والإبهام. حافظ على استرخاء اليد. افرد الأصابع للخارج ببطء ضد مقاومة الشريط. ثبّت وضع الفتح لمدة 3–5 ثوانٍ. استرخِ وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = '6ea6108d-11dd-4795-a890-56e0ff3a5309';  -- Finger Extension Using Band
UPDATE "Exercises" SET "Description" = 'Hold a small soft object between your thumb and one finger. Squeeze the object firmly using pinch pressure. Hold the pinch for 3–5 seconds. Release and switch to the next finger. Continue through each finger of the hand.', "DescriptionAr" = 'أمسك جسماً صغيراً طرياً بين الإبهام وأحد الأصابع. اضغط الجسم بقوة باستخدام حركة القرص. ثبّت القرصة لمدة 3–5 ثوانٍ. استرخِ وانتقل إلى الإصبع التالي. تابع مع جميع أصابع اليد.', "UpdatedAt" = now() WHERE "ExerciseId" = '232e1abc-6724-4aeb-a87e-87bd1c17fe6a';  -- Finger Pinches
UPDATE "Exercises" SET "Description" = 'Rest the hand flat with fingers together. Use the other hand to gently stretch fingers apart. Then stretch fingers backward one at a time. Hold each stretch for 10–15 seconds. Release and repeat as needed.', "DescriptionAr" = 'ضع اليد مسطحة والأصابع مضمومة. استخدم اليد الأخرى لتباعد الأصابع بلطف. ثم اسحب كل إصبع للخلف واحداً تلو الآخر. ثبّت كل شدّة لمدة 10–15 ثانية. استرخِ ويكرر عند الحاجة.', "UpdatedAt" = now() WHERE "ExerciseId" = 'd21e6321-ccb6-4915-ade9-b96c29aafa93';  -- Finger Stretch
UPDATE "Exercises" SET "Description" = 'Place the hand flat on a table, palm down. Keep all fingers straight and together. Slowly spread the fingers apart as wide as possible. Hold the spread position for 3–5 seconds. Bring fingers back together and repeat.', "DescriptionAr" = 'ضع اليد مسطحة على طاولة وراحة اليد للأسفل. حافظ على استقامة الأصابع مضمومة. فرّق الأصابع ببطء لأقصى مدى ممكن. ثبّت وضع التباعد لمدة 3–5 ثوانٍ. أعد الأصابع للتقارب وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '3c6e8fbb-f8e8-42e2-ba61-95b4100e71b5';  -- Fingers Abduction
UPDATE "Exercises" SET "Description" = 'Rest the forearm on a table with the palm down. Start with all fingers bent slightly. Slowly straighten all fingers, lifting them upward. Hold at the extended position briefly. Return to the starting bend and repeat.', "DescriptionAr" = 'ضع الساعد على طاولة وراحة اليد للأسفل. ابدأ مع ثني جميع الأصابع قليلاً. افرد كل الأصابع ببطء ورفعها للأعلى. ثبّت في وضع الفرد لحظة. عد إلى الوضع المثنى وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '1f968a2b-fa39-4b88-91c9-b29ebebc635e';  -- Fingers Extension
UPDATE "Exercises" SET "Description" = 'Make a tight fist with the affected hand. Use the other hand to gently press over the fist. Increase the squeeze slightly at the end range. Hold the pressure for 3–5 seconds. Release and repeat.', "DescriptionAr" = 'كوّن قبضة قوية باليد المصابة. استخدم اليد الأخرى للضغط بلطف فوق القبضة. زد الضغط قليلاً في نهاية الحركة. ثبّت الضغط لمدة 3–5 ثوانٍ. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '479ae9bd-42b1-4ff9-8d28-b9effc93e680';  -- Fist Overpressure
UPDATE "Exercises" SET "Description" = 'Stand with a foam roller against a wall behind your back. Place your forearms on the wall in a goalpost position. Slowly slide the arms upward along the wall. Keep contact with the roller throughout. Lower the arms slowly and repeat.', "DescriptionAr" = 'قف مع وضع اسطوانة الفوم بين الظهر والحائط. ضع ساعديك على الحائط بوضع مرمى. اسحب الذراعين ببطء للأعلى على الحائط. حافظ على تلامس الاسطوانة طوال الحركة. أنزل الذراعين ببطء وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'd42fc844-88f4-43cf-a9ee-323e2c6f922b';  -- Foam Roller Wall Slides
UPDATE "Exercises" SET "Description" = 'Sit with the elbow bent at 90 degrees at your side. Hold a light object in your hand. Rotate the palm upward (supination), then downward (pronation). Keep the elbow tucked and still. Move slowly through the full range.', "DescriptionAr" = 'اجلس مع ثني الكوع 90 درجة بجانب الجسم. أمسك جسماً خفيفاً باليد. أدر راحة اليد للأعلى (استلقاء) ثم للأسفل (كبّ). حافظ على تثبيت الكوع بجانب الجسم. تحرك ببطء عبر النطاق الكامل.', "UpdatedAt" = now() WHERE "ExerciseId" = 'd6f1b9da-6612-4173-929d-370313a4dc11';  -- Forearm Supination and Pronation
UPDATE "Exercises" SET "Description" = 'Stand next to a wall with the arm at your side. Keep the elbow straight and press the back of the hand against the wall. Push outward as if lifting the arm sideways. Hold the push for 10 - 20 seconds without moving. Relax and repeat.', "DescriptionAr" = 'قف بجانب حائط والذراع بجانب الجسم. حافظ على استقامة الكوع واضغط ظهر اليد على الحائط. ادفع للخارج كأنك ترفع الذراع للجانب. ثبّت الدفع لمدة 20–10 ثوانٍ دون حركة. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '0edf600f-90e7-4d42-9ab6-6e14978ea097';  -- Isometric Lateral Raises
UPDATE "Exercises" SET "Description" = 'Sit with the elbow bent at 90 degrees at your side. Hold a light weight in your hand, palm facing down. Slowly rotate the forearm so the palm faces upward. Keep the elbow tucked close to the body. Return slowly to start and repeat.', "DescriptionAr" = 'اجلس مع ثني الكوع 90 درجة بجانب الجسم. أمسك وزناً خفيفاً باليد وراحة اليد للأسفل. أدر الساعد ببطء حتى تصبح راحة اليد للأعلى. حافظ على تثبيت الكوع بجانب الجسم. عد ببطء البداية وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '9752b609-3acd-4420-bbcf-ce36f2542c71';  -- Forearm Supination
UPDATE "Exercises" SET "Description" = 'Extend the affected arm in front with palm facing up. Bend the thumb into the palm. Wrap the fingers over the thumb to make a fist. Slowly bend the wrist downward and toward the pinky. Hold 15–20 seconds, feeling a stretch at the thumb side.', "DescriptionAr" = 'مدّ الذراع المصابة للأمام وراحة اليد للأعلى. اثنِ الإبهام داخل راحة اليد. لفّ الأصابع فوق الإبهام لتكوين قبضة. اثنِ الرسغ ببطء للأسفل ونحو الخنصر. ثبّت 15–20 ثانية مع الشعور بالشد في جهة الإبهام.', "UpdatedAt" = now() WHERE "ExerciseId" = 'e1b9a5a9-7694-4e7d-9179-bb82878850d3';  -- Finkelstein Stretch
UPDATE "Exercises" SET "Description" = 'Start on all fours on a soft mat. Bring the knees wide apart with feet pointing outward. Lower the forearms to the floor for support. Push the hips gently backward for a deeper stretch. Hold 20–30 seconds then release.', "DescriptionAr" = 'ابدأ على اليدين والركبتين على سجادة ناعمة. فرد الركبتين للجانبين والقدمين للخارج. أنزل الساعدين على الأرض للدعم. ادفع الوركين للخلف بلطف لتعميق الشد. ثبّت 20–30 ثانية ثم استرخِ.', "UpdatedAt" = now() WHERE "ExerciseId" = '1ae9f9f5-db9b-4795-97c9-e245ec624531';  -- Frog Stretch
UPDATE "Exercises" SET "Description" = 'Kneel on one knee with the other foot flat in front. Keep the back straight and core engaged. Shift your hips forward gently. Feel the stretch across the front of the hip flexors. Hold 20–30 seconds then switch sides.', "DescriptionAr" = 'اركع على ركبة واحدة والقدم الأخرى مسطحة أمامك. حافظ على استقامة الظهر وشد عضلات البطن. ادفع الوركين للأمام بلطف. تشعر بالشد في مقدمة الفخذ الأمامي. ثبّت 20–30 ثانية ثم بدّل.', "UpdatedAt" = now() WHERE "ExerciseId" = '5b5a8952-46b6-4f25-a58b-240b6be51929';  -- Hip Flexors Stretch
UPDATE "Exercises" SET "Description" = 'Rest your hand flat on a table, palm up. Stabilize the middle joint of the finger with your other hand. Slowly flex only the fingertip joint. Hold at the bent position briefly. Straighten slowly and repeat with each finger.', "DescriptionAr" = 'ضع يدك مسطحة على طاولة وراحة اليد للأعلى. ثبّت المفصل الأوسط للإصبع باليد الأخرى. اثنِ فقط مفصل رأس الإصبع للأسفل ببطء. ثبّت في وضع الثني لحظة. افرد ببطء وكرر مع كل إصبع.', "UpdatedAt" = now() WHERE "ExerciseId" = 'bd92638f-12b0-4881-af38-4cc04278473d';  -- Isolated DIP Joint Flexion
UPDATE "Exercises" SET "Description" = 'Rest the forearm on a table with the palm up. Keep the finger joints straight except the knuckle. Slowly bend the finger at the knuckle joint only. Hold at the bent position briefly. Straighten and repeat with each finger.', "DescriptionAr" = 'ضع الساعد على طاولة وراحة اليد للأعلى. حافظ على استقامة مفاصل الأصابع ما عدا المفصل الأساسي. اثنِ الإصبع فقط من المفصل الأساسي ببطء. ثبّت في وضع الثني لحظة. افرد وكرر مع كل إصبع.', "UpdatedAt" = now() WHERE "ExerciseId" = '8cdef364-4bed-45fd-bb1d-e1fd43a3f9e7';  -- Isolated MCP Joint Flexion
UPDATE "Exercises" SET "Description" = 'Rest the hand flat on a table, palm up. Keep the fingers relaxed and still. Slowly bend the thumb toward the palm. Hold the bent position for 3–5 seconds. Return the thumb to start and repeat.', "DescriptionAr" = 'ضع اليد مسطحة على طاولة وراحة اليد للأعلى. حافظ على استرخاء الأصابع وثباتها. اثنِ الإبهام ببطء نحو راحة اليد. ثبّت وضع الثني لمدة 3–5 ثوانٍ. عد بالإبهام للبداية وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '429a4d5d-66d1-4798-a263-f3a8dd451c1c';  -- Isolated Thumb Flexion
UPDATE "Exercises" SET "Description" = 'Stand next to a wall with the elbow bent 90 degrees at your side. Place the back of your hand against the wall. Push outward into the wall as if rotating the arm out. Hold the push for 10 - 20 seconds without moving. Relax and repeat.', "DescriptionAr" = 'قف بجانب حائط و الكوع مثني 90 درجة بجانب الجسم. ضع ظهر اليد على الحائط. ادفع للخارج ضد الحائط كأنك تدير الذراع للخارج. ثبّت الدفع لمدة 20–10 ثوانٍ دون حركة. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '7d98f75e-8e51-48b5-91c4-576c99394cd0';  -- Isometric External Rotation
UPDATE "Exercises" SET "Description" = 'Stand next to a wall with the elbow bent 90 degrees. Place the palm of the hand against the wall. Push into the wall as if rotating the arm inward. Hold the push for 20–10 seconds without moving. Relax and repeat.', "DescriptionAr" = 'قف بجانب حائط و الكوع مثني 90 درجة. ضع راحة اليد على الحائط. ادفع الحائط كأنك تدير الذراع للداخل. ثبّت الدفع لمدة 20–10 ثوانٍ دون حركة. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'fd4344b8-156a-4e47-9bce-83bd818b2e9f';  -- Isometric Internal Rotation
UPDATE "Exercises" SET "Description" = 'Stand with your back against a wall. Keep the arm straight at your side. Press the back of the hand backward into the wall. Hold the push for 20–10 seconds without moving. Relax and repeat.', "DescriptionAr" = 'قف وظهرك ملاصق للحائط. حافظ على استقامة الذراع بجانب الجسم. اضغط ظهر اليد للخلف على الحائط. ثبّت الدفع لمدة 20–10 ثوانٍ دون حركة. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'ed024269-8421-40c3-a635-2e77a9d6c5d7';  -- Isometric Shoulder Extension
UPDATE "Exercises" SET "Description" = 'Stand facing a wall at arm''s length. Keep the arm straight and place the palm on the wall. Push the hand forward into the wall. Hold the push for 20–10 seconds without moving. Relax and repeat.', "DescriptionAr" = 'قف مواجهاً الحائط على مسافة ذراع. حافظ على استقامة الذراع وضع راحة اليد على الحائط. ادفع اليد للأمام على الحائط. ثبّت الدفع لمدة 20–10 ثوانٍ دون حركة. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '94261b26-dfe6-45a2-b284-138eab6cc31b';  -- Isometric Shoulder Flexion
UPDATE "Exercises" SET "Description" = 'Rest the forearm on a table with the palm down. Place the other hand on top of the affected hand. Try to lift the hand upward while the other hand resists. Hold the push for 20–10 seconds without movement. Relax and repeat.', "DescriptionAr" = 'ضع الساعد على طاولة وراحة اليد للأسفل. ضع اليد الأخرى فوق اليد المصابة. حاول رفع اليد للأعلى مع مقاومة اليد الأخرى. ثبّت الدفع لمدة 20–10 ثوانٍ دون حركة. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'ba4bbabc-db9b-4e51-b7a2-3d5f9f19fb6c';  -- Isometric Wrist Extension
UPDATE "Exercises" SET "Description" = 'Sit on the floor with one leg straight in front. flex the other knee with the foot against the inner thigh. Slowly hinge forward from the hips. Reach the hands toward the straight foot. Hold 20–30 seconds then switch sides.', "DescriptionAr" = 'اجلس على الأرض مع فرد ساق واحدة أمامك. اثنِ الركبة الأخرى والقدم على الفخذ الداخلي. انحنِ للأمام ببطء من الوركين. مدّ اليدين نحو القدم المستقيمة. ثبّت 20–30 ثانية ثم بدّل.', "UpdatedAt" = now() WHERE "ExerciseId" = '745d4cbc-277c-4cc5-ad29-fd334641e722';  -- Knee-Supported Hamstring Stretch
UPDATE "Exercises" SET "Description" = 'Lie face down on the floor. Place your hands under your shoulders like a push-up. Slowly press up, lifting the chest and upper back. Keep the hips flat on the floor. Hold 3–5 seconds then lower and repeat.', "DescriptionAr" = 'استلقِ على البطن على الأرض. وضع اليدين تحت الكتفين تمارين الضغط. ادفع للأعلى ببطء لرفع الصدر وأعلى الظهر. حافظ على تثبيت الوركين على الأرض. ثبّت 3–5 ثوانٍ ثم أنزل وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'fd550077-57f8-4bd6-9f33-3c1d184ec353';  -- McKenzie Stretch
UPDATE "Exercises" SET "Description" = 'Kneel with hands under shoulders and knees under hips. Keep a neutral spine as your starting position. Slowly arch the back by lifting the chest and looking up. Feel a stretch along the front of the body. Return to neutral and repeat gently.', "DescriptionAr" = 'اركع مع اليدين تحت الكتفين والركبتين تحت الوركين. حافظ على وضع محايد للعمود الفقري كبداية. قوّس الظهر ببطء برفع الصدر والنظر للأعلى. اشعر بالشد على مقدمة الجسم. عد للوضع المحايد وكرر بلطف.', "UpdatedAt" = now() WHERE "ExerciseId" = '97e97d92-6cd7-473d-9619-7fceb48671b4';  -- Kneeling Back Extensions
UPDATE "Exercises" SET "Description" = 'Kneel in front of a chair or bench. Place both forearms on the surface, palms up. Sit the hips back toward the heels. Let the chest drop toward the floor. Hold 20–30 seconds then release.', "DescriptionAr" = 'أركع أمام كرسي أو مقعد. ضع الساعدين على السطح وراحة اليدين للأعلى. ادفع الوركين للخلف نحو الكعبين. اترك الصدر ينزل نحو الأرض. ثبّت 20–30 ثانية ثم استرخِ.', "UpdatedAt" = now() WHERE "ExerciseId" = '23bfd228-1480-4c82-a117-252bd9d296f7';  -- Kneeling Lats Stretch
UPDATE "Exercises" SET "Description" = 'Stand tall with a light dumbbell in each hand. Keep the arms straight at your sides. Raise both arms out to the sides to shoulder height. Pause briefly at the top position. Lower the weights slowly and repeat.', "DescriptionAr" = 'قف بشكل مستقيم دمبل خفيف بكل يد. حافظ على استقامة الذراعين بجانب الجسم. ارفع الذراعين للجانبين حتى مستوى الكتف. توقف لحظة في وضع الأعلى. أنزل الأوزان ببطء وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = 'cdb1883d-c99d-4e04-8da9-5def067fcd38';  -- Lateral Raises
UPDATE "Exercises" SET "Description" = 'Kneel on the floor and sit back on your heels. Place both palms together in front of you. Reach the arms forward along the floor. Press the chest and armpits toward the ground. Hold 20–30 seconds while breathing slowly.', "DescriptionAr" = 'اركع على الأرض واجلس على كعبيك. ضع راحتي اليدين معاً أمامك. مدّ الذراعين للأمام على الأرض. اضغط الصدر والإبطين نحو الأرض. ثبّت 20–30 ثانية مع التنفس البطيء.', "UpdatedAt" = now() WHERE "ExerciseId" = 'b1cc071c-6f42-4a19-87b7-d2806b837059';  -- Lats Prayer Stretch
UPDATE "Exercises" SET "Description" = 'Sit on the floor with legs spread wide apart. Keep the knees pointing upward and toes flexed. Slowly hinge forward from the hips. Walk the hands forward as far as comfortable. Hold 20–30 seconds then return upright.', "DescriptionAr" = 'اجلس على الأرض مع فتح الساقين للجانبين. حافظ على توجيه الركبتين للأعلى وثني أصابع القدم. انحنِ للأمام ببطء من الوركين. مدّ اليدين للأمام قدر ما تسمح الراحة. ثبّت 20–30 ثانية ثم عاد للجلوس.', "UpdatedAt" = now() WHERE "ExerciseId" = '755d761b-f878-433b-ac17-d5a989f768ac';  -- Legs Split with Trunk Flexion
UPDATE "Exercises" SET "Description" = 'Sit upright and look down toward the opposite armpit. Place the same-side hand on top of your head. Gently pull the head diagonally forward and down. Feel the stretch along the back of the neck. Hold 20–30 seconds then switch sides.', "DescriptionAr" = 'اجلس بشكل مستقيم انظر للأسفل نحو الإبط المعاكس. ضع يد نفس الجهة فوق الرأس. اسحب الرأس بلطف قطرياً للأمام ولأسفل. اشعر بالشد على خلفية الرقبة. ثبّت 20–30 ثانية ثم بدّل.', "UpdatedAt" = now() WHERE "ExerciseId" = '21503aeb-3224-4f57-9007-9a62fffd99b6';  -- Levator Scapula Stretch
UPDATE "Exercises" SET "Description" = 'Sit on the floor with legs straight in front and a towel under the affected leg’s heel. Keep the back upright and hands beside your hips. Slowly slide one heel toward the buttock, bending the knee. Then slide the heel back out to straight. Repeat with the same leg, then switch.', "DescriptionAr" = 'اجلس على الأرض مع فرد الساقين أمامك ومنشفة تحت الكعب الساق المصابة. حافظ على استقامة الظهر واليدان بجانب الوركين. اسحب كعب واحد ببطء نحو الأرداف مع ثني الركبة. ثم اسحب الكعب للخلف حتى تستقيم الساق. كرر نفس الساق ثم بدّل.', "UpdatedAt" = now() WHERE "ExerciseId" = 'eaf00107-5b83-4cf3-a90b-5bb2dc6e3f27';  -- Long Sitting Heel Slides
UPDATE "Exercises" SET "Description" = 'Lie on your back with knees bent, feet flat on the floor. Keep the shoulders pressed to the ground. Slowly drop both knees to one side. Feel a gentle rotation in the lower back. Return to the center and drop to the other side.', "DescriptionAr" = 'استلقِ على ظهرك مع ثني الركبتين والقدمين على الأرض. حافظ على تثبيت الكتفين على الأرض. أنزل الركبتين ببطء إلى جانب واحد. أشعر بلف لطيف في أسفل الظهر. عد للوسط وأنزل للجانب الآخر.', "UpdatedAt" = now() WHERE "ExerciseId" = '5d24be16-d521-4b9b-92c5-bbc34ee26f9c';  -- Lumbar Rotation
UPDATE "Exercises" SET "Description" = 'Rest the forearm on a table with the palm up. Keep the finger joints straight. Bend only the knuckles, folding the fingers as one unit. Hold at the bent position briefly. Straighten slowly and repeat.', "DescriptionAr" = 'ضع الساعد على طاولة وراحة اليد للأعلى. حافظ على استقامة مفاصل الأصابع. اثنِ المفاصل الأساسية فقط لطي الأصابع كوحدة. ثبّت وضع الثني لحظة. افرد ببطء وكرر التمرين.', "UpdatedAt" = now() WHERE "ExerciseId" = '8d015525-2268-4e77-bd75-bcc744435dcf';  -- Metacarpals Flexion
UPDATE "Exercises" SET "Description" = 'Place a soft ball between your forehead and a wall. Stand with feet slightly apart for balance. Press the forehead gently into the ball. Hold the press for 20–10 seconds. Relax and repeat.', "DescriptionAr" = 'ضع كرة طرية بين جبهتك والحائط. قف والقدمان متباعدتان قليلاً للتوازن. اضغط الجبهة بلطف على الكرة. ثبّت الضغطة لمدة 20–10 ثوانٍ. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '750b5eb5-2a29-40b1-affe-9718df4f8d56';  -- Neck Frontal Ball Stability
UPDATE "Exercises" SET "Description" = 'Sit or stand tall with shoulders relaxed. Slowly turn the head to one side as far as comfortable. Hold at the end range for 2–3 seconds. Return to center then turn to the other side. Repeat several rotations each way.', "DescriptionAr" = 'اجلس أو قف بشكل مستقيم مع استرخاء الكتفين. أدر الرأس ببطء إلى جهة واحدة قدر ما تسمح الراحة. ثبّت في نهاية الحركة لمدة 2–3 ثوانٍ. عد للوسط ثم أدر للجهة الأخرى. كرر عدة دورات لكل جهة.', "UpdatedAt" = now() WHERE "ExerciseId" = 'a2f0fec5-742d-4dec-b5e6-2c235d22a896';  -- Neck Full Rotation
UPDATE "Exercises" SET "Description" = 'Place a soft ball between the back of your head and a wall. Stand with feet slightly apart for balance. Press the back of the head gently into the ball. Hold the press for 20–10 seconds. Relax and repeat.', "DescriptionAr" = 'ضع كرة طرية بين مؤخرة الرأس والحائط. قف والقدمان متباعدتان قليلاً للتوازن. اضغط مؤخرة الرأس بلطف على الكرة. ثبّت الضغطة لمدة 5–10 ثوانٍ. استرخِ وكرر.', "UpdatedAt" = now() WHERE "ExerciseId" = '53821f7b-3950-4c7a-9ec0-d8d2a6f934ee';  -- Neck Occipital Ball Stability
UPDATE "Exercises" SET "Description" = 'Place a soft ball between the side of your head and a wall. Stand with feet slightly apart for balance. Gently press the side of your head into the ball without moving your neck. Hold the press for 20–10 seconds. Relax and repeat on the other side.', "DescriptionAr" = 'ضع كرة طرية بين جانب رأسك والحائط. قف والقدمان متباعدتان قليلاً للتوازن. اضغط جانب رأسك بلطف على الكرة دون تحريك الرقبة. ثبّت الضغطة لمدة 20–10 ثوانٍ. استرخِ وكرر التمرين على الجانب الآخر.', "UpdatedAt" = now() WHERE "ExerciseId" = '5be1dc55-22c5-472a-ac36-1efa23d943f4';  -- Neck Side Ball Stability

